// Helper functions to navigate the new structure

function safeDecodeURIComponent(value: string): string {
  try {
    return decodeURIComponent(value);
  } catch {
    return value;
  }
}

export function toPrettyCurriculumSlug(segment: string): string {
  return safeDecodeURIComponent(segment)
    .trim()
    .replace(/_/g, '-')
    .replace(/[^a-zA-Z0-9-]+/g, '-')
    .replace(/-+/g, '-')
    .replace(/^-|-$/g, '')
    .toLowerCase();
}

function findBySlug<T extends { slug: string }>(items: T[], rawSlug: string | undefined): T | undefined {
  if (!rawSlug) return undefined;
  const prettySlug = toPrettyCurriculumSlug(rawSlug);
  return items.find(item => item.slug === rawSlug || toPrettyCurriculumSlug(item.slug) === prettySlug);
}

export function normalizeSlug(slug: string[]): string[] {
  if (slug.length === 0) return [];

  const [rawTierSlug, rawSectionSlug, rawTopicSlug] = slug;
  const courseModule = findBySlug(curriculumData, rawTierSlug);
  if (!courseModule) return [];

  if (slug.length === 1) {
    const firstSection = courseModule.sections[0];
    if (!firstSection) return [];
    const firstTopic = firstSection.topics.find(t => t.slug === 'index') ?? firstSection.topics[0];
    if (!firstTopic) return [];
    return [courseModule.slug, firstSection.slug, firstTopic.slug];
  }

  const section = findBySlug(courseModule.sections, rawSectionSlug);
  if (!section) return [];

  if (slug.length >= 3) {
    const topic = findBySlug(section.topics, rawTopicSlug);
    if (!topic) return [];
    return [courseModule.slug, section.slug, topic.slug];
  }

  const topic = section.topics.find(t => t.slug === 'index') ?? section.topics[0];
  if (!topic) return [];
  return [courseModule.slug, section.slug, topic.slug];
}

export function findTopicBySlug(slug: string[]): Topic | undefined {
  const normalized = normalizeSlug(slug);
  if (normalized.length !== 3) return undefined;
  const [tierSlug, sectionSlug, topicSlug] = normalized;
  const courseModule = curriculumData.find(m => m.slug === tierSlug);
  if (!courseModule) return undefined;
  const section = courseModule.sections.find(s => s.slug === sectionSlug);
  if (!section) return undefined;
  return section.topics.find(t => t.slug === topicSlug);
}

export function getBreadcrumbs(slug: string[]): { title: string, path: string }[] {
  const normalized = normalizeSlug(slug);
  if (normalized.length !== 3) return [];
  const [tierSlug, sectionSlug, topicSlug] = normalized;
  const breadcrumbs: { title: string, path: string }[] = [];
  const courseModule = curriculumData.find(m => m.slug === tierSlug);
  if (!courseModule) return breadcrumbs;

  breadcrumbs.push({ title: "Curriculum", path: `/curriculum` });
  breadcrumbs.push({ title: courseModule.title, path: `/curriculum/${courseModule.slug}` });

  const section = courseModule.sections.find(s => s.slug === sectionSlug);
  if (!section) return breadcrumbs;
  breadcrumbs.push({ title: section.title, path: `/curriculum/${courseModule.slug}/${section.slug}` });

  const topic = section.topics.find(t => t.slug === topicSlug);
  if (topic) {
    breadcrumbs.push({ title: topic.title, path: `/curriculum/${courseModule.slug}/${section.slug}/${topic.slug}` });
  }

  return breadcrumbs;
}

export interface NavTopic extends Topic {
  /** Folder name of the module (section) this topic belongs to. */
  moduleSlug: string;
  track: 'core' | 'elective';
}

function allNavTopics(): NavTopic[] {
  const all: NavTopic[] = [];
  curriculumData.forEach(m => {
    m.sections.forEach(s => {
      s.topics.forEach(t => {
        all.push({ ...t, slug: `${m.slug}/${s.slug}/${t.slug}`, moduleSlug: s.slug, track: s.track ?? 'core' });
      });
    });
  });
  return all;
}

/**
 * Previous and next lessons along the learning path. From a core lesson the
 * path skips elective modules (they stay reachable from the outline); inside a
 * module, and from an elective, every lesson is visited in order.
 */
export function findPrevNextTopics(slug: string[]): { prev: Topic | undefined, next: Topic | undefined } {
  const normalized = normalizeSlug(slug);
  if (normalized.length !== 3) return { prev: undefined, next: undefined };

  const allTopics = allNavTopics();
  const currentIndex = allTopics.findIndex(t => t.slug === normalized.join('/'));
  if (currentIndex === -1) return { prev: undefined, next: undefined };
  const current = allTopics[currentIndex];
  const onPath = (t: NavTopic) => current.track === 'elective' || t.track === 'core' || t.moduleSlug === current.moduleSlug;

  let prev: NavTopic | undefined;
  for (let i = currentIndex - 1; i >= 0; i -= 1) {
    if (onPath(allTopics[i])) { prev = allTopics[i]; break; }
  }
  let next: NavTopic | undefined;
  for (let i = currentIndex + 1; i < allTopics.length; i += 1) {
    if (onPath(allTopics[i])) { next = allTopics[i]; break; }
  }
  const strip = (t?: NavTopic): Topic | undefined => (t ? { title: t.title, slug: t.slug, description: t.description } : undefined);
  return { prev: strip(prev), next: strip(next) };
}

/** The section (module) for a lesson slug, with its manifest metadata. */
export function findSectionBySlug(slug: string[]): Section | undefined {
  const normalized = normalizeSlug(slug);
  if (normalized.length !== 3) return undefined;
  const [tierSlug, sectionSlug] = normalized;
  return curriculumData.find(m => m.slug === tierSlug)?.sections.find(s => s.slug === sectionSlug);
}

/** Canonical URL of a module's first lesson, given its folder name. */
export function moduleHref(moduleSlug: string): string | undefined {
  for (const m of curriculumData) {
    const s = m.sections.find(x => x.slug === moduleSlug);
    if (s) return `/curriculum/${m.slug}/${s.slug}/${(s.topics.find(t => t.slug === 'index') ?? s.topics[0])?.slug ?? 'index'}`;
  }
  return undefined;
}

// ---- Derived convenience types for the application UI ----

// The curriculumData array represents the high level tiers of the course. The
// UI components expect a `Tier` type with a list of `modules`.  Each module in
// turn contains a list of lessons.  The existing data maps cleanly onto this
// structure where a "Module" is a tier and each "Section" is a module.  The
// topics within a section represent the lessons.

export type Tier = Module;
export type Lesson = Topic;
export interface ModuleEntry {
  id: string;
  title: string;
  slug: string;
  lessons: Lesson[];
}

export const tiers: Tier[] = curriculumData;

export function getModules(tier: Tier): ModuleEntry[] {
  return tier.sections.map(section => ({
    id: section.slug,
    title: section.title,
    slug: section.slug,
    lessons: section.topics,
  }));
}

